// ai-agents/orchestrator/src/policies.ts (part 1): timeouts are safety nets, not work limits.
import { proxyActivities, type ActivityOptions, type RetryPolicy } from "@temporalio/workflow";
import type * as activities from "./activities/index.js";

export const SHORT: ActivityOptions = { startToCloseTimeout: "5 minutes" };
// startToCloseTimeout is required by the SDK and is NOT a work limit: when 7 days pass, the retry
// re-attaches to the harness still running on the VM. The 2-minute heartbeat catches a dead worker.
export const LONG: ActivityOptions = { startToCloseTimeout: "7 days", heartbeatTimeout: "2 minutes" };

// ai-agents/orchestrator/src/policies.ts (part 2): one RetryPolicy per kind of call
const NEVER_RETRY = ["ScopeDenied", "PlanRejected", "NeedsPerson", "StoppedByPerson"];
export const AWS: RetryPolicy = { initialInterval: "1s", backoffCoefficient: 2, maximumInterval: "1 minute",
  maximumAttempts: 10, nonRetryableErrorTypes: NEVER_RETRY };
export const PEOPLE_APIS: RetryPolicy = { initialInterval: "5s", backoffCoefficient: 2, maximumInterval: "5 minutes",
  nonRetryableErrorTypes: NEVER_RETRY }; // no attempt limit: G3-39 pauses the ticket on long outages
export const HARNESS_STEP: RetryPolicy = { maximumAttempts: 1 }; // recovery (G3-27) decides, not blind retries

/** One place for timeouts and retries, so every workflow behaves the same. */
export const act = proxyActivities<typeof activities>({ ...LONG, retry: AWS });
export const peopleApis = proxyActivities<typeof activities>({ ...SHORT, retry: PEOPLE_APIS });

import { activityInfo, heartbeat } from "@temporalio/activity";

export async function slowWork(steps: number): Promise<string> {
  const done = (activityInfo().heartbeatDetails as number | undefined) ?? 0; // what a dead attempt reported
  if (done > 0) console.log(`attempt ${activityInfo().attempt}: resuming after step ${done}`);
  for (let i = done + 1; i <= steps; i++) {
    await new Promise((r) => setTimeout(r, 1000)); // one second of "work"
    heartbeat(i); // proof of life, and how far we got
  }
  return `did ${steps} steps`;
}

// ai-agents/orchestrator/src/activities/sandbox.ts (sketch of G3-20): start the harness once, then follow it
import { heartbeat } from "@temporalio/activity";
import { ApplicationFailure } from "@temporalio/common";

export async function workInSandbox(vm: Vm, task: Task): Promise<RunResult> {
  if (!(await harnessRunning(vm))) await startHarness(vm, task); // systemd-run over SSM; a retry finds it running
  for (;;) {
    const beat = await broker.lastHeartbeat(task.runId); // the harness beats every 30 s from its own timer
    if (beat.state !== "running") return beat.result; // done, needs_answer, preempted or failed
    if (beat.ageMs > 5 * 60_000) throw ApplicationFailure.create({ type: "SandboxDead", nonRetryable: true });
    heartbeat({ step: beat.step, checkpoint: beat.checkpoint }); // tells Temporal this worker is alive
    await new Promise((r) => setTimeout(r, 30_000));
  }
}

// ai-agents/orchestrator/src/workflows/ticket-to-pr.ts (part of G3-24): workflow code
const inSandbox = async (task: Task, size: Size): Promise<RunResult> => {
  const vm = await act.acquireSandbox({ runId: workflowInfo().runId, size, agent: "nova", jiraKey: t.key });
  try {
    await act.freshenSandbox(vm, base);
    return await act.workInSandbox(vm, task); // heartbeats; no work-time limit
  } finally {
    await CancellationScope.nonCancellable(() => act.releaseSandbox(vm)); // always: no VM is left behind
  }
};

